package com.giftmarket.admin.service;import com.giftmarket.admin.exception.AdminReturnException;import com.giftmarket.auth.exception.AuthenticationException;import com.giftmarket.global.storage.service.StorageService;import com.giftmarket.order.entity.*;import com.giftmarket.order.repository.*;import com.giftmarket.payment.repository.*;import com.giftmarket.user.entity.*;import com.giftmarket.user.repository.UserRepository;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.BDDMockito.given;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class AdminReturnServiceTest{@Mock UserRepository users;@Mock ReturnRequestRepository returns;@Mock ReturnRequestItemRepository items;@Mock ReturnRequestImageRepository images;@Mock PaymentRepository payments;@Mock PaymentCancellationRepository refunds;@Mock StorageService storage;@Mock User admin;AdminReturnService service;@BeforeEach void setUp(){service=new AdminReturnService(users,returns,items,images,payments,refunds,storage);}void admin(){given(users.findById(1L)).willReturn(Optional.of(admin));given(admin.getRole()).willReturn(UserRole.ADMIN);}
@Test void rejectsNullAdmin(){assertThatThrownBy(()->service.getReturns(null,0,20,null,null,null)).isInstanceOf(AuthenticationException.class).hasMessage("인증이 필요합니다.");verifyNoInteractions(returns);}@Test void rejectsMissingAdmin(){given(users.findById(1L)).willReturn(Optional.empty());assertThatThrownBy(()->service.getReturn(1L,2L)).isInstanceOf(AuthenticationException.class).hasMessage("사용자를 찾을 수 없습니다.");}@Test void rejectsNonAdmin(){given(users.findById(1L)).willReturn(Optional.of(admin));given(admin.getRole()).willReturn(UserRole.USER);assertThatThrownBy(()->service.getReturn(1L,2L)).isInstanceOf(AuthenticationException.class).hasMessage("관리자 권한이 필요합니다.");}
@Test void passesTrimmedFiltersPaginationAndSort(){admin();given(returns.findAdminReturns(any(),any(),any(),any())).willReturn(Page.empty());service.getReturns(1L,2,20,"  gift  ",ReturnRequestStatus.INSPECTED,ReturnResponsibility.BUYER);ArgumentCaptor<Pageable>p=ArgumentCaptor.forClass(Pageable.class);verify(returns).findAdminReturns(eq("gift"),eq(ReturnRequestStatus.INSPECTED),eq(ReturnResponsibility.BUYER),p.capture());assertThat(p.getValue().getPageNumber()).isEqualTo(2);assertThat(p.getValue().getSort().getOrderFor("requestedAt").isDescending()).isTrue();assertThat(p.getValue().getSort().getOrderFor("id").isDescending()).isTrue();}
@Test void emptyPageSkipsBatchQueries(){admin();given(returns.findAdminReturns(any(),any(),any(),any())).willReturn(Page.empty());assertThat(service.getReturns(1L,0,20," ",null,null).content()).isEmpty();verifyNoInteractions(items,refunds);}@Test void throwsNotFound(){admin();given(returns.findAdminById(99L)).willReturn(Optional.empty());assertThatThrownBy(()->service.getReturn(1L,99L)).isInstanceOf(AdminReturnException.class).hasMessage("반품 요청을 찾을 수 없습니다.");}}
